function safeHttpUrl(value){try{const u=new URL(String(value||'').trim());return (u.protocol==='http:'||u.protocol==='https:')&&!u.username&&!u.password&&!!u.hostname}catch{return false}}
if(typeof module!=='undefined'&&module.exports)module.exports={safeHttpUrl};
if(typeof document==='undefined')return;
const q=(s,r=document)=>r.querySelector(s),qa=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fa=v=>String(v??'').replace(/\d/g,d=>'۰۱۲۳۴۵۶۷۸۹'[d]);
const fmtBytes=n=>{n=Number(n)||0;if(n<1024)return fa(n)+' بایت';if(n<1048576)return fa((n/1024).toFixed(1))+' کیلوبایت';return fa((n/1048576).toFixed(1))+' مگابایت'};
const fmtDate=v=>v&&Number.isFinite(Date.parse(v))?new Date(v).toLocaleString('fa-IR'):'—';
const canFeature=(featureKey,action='view')=>window.BamcoAccess?.can?.(featureKey,action)===true;
