// Use the same top-level Chrome PDF flow as vehicle previewForm.
async function previewPdfInBrowser(doc,button){
 const viewer=window.open('about:blank','_blank');
 if(!viewer){notice('مرورگر تب پیش‌نمایش را مسدود کرده است؛ اجازه باز شدن تب جدید را فعال کنید.',true);return}
 viewer.opener=null;setBusy(button,true,'در حال دریافت…');
 try{
  viewer.document.title='در حال دریافت PDF…';
  viewer.document.body.textContent='در حال دریافت فایل…';
  const blob=await privateFile(doc.storage_path);
  const header=new TextDecoder('ascii').decode(await blob.slice(0,1024).arrayBuffer());
  if(!header.includes('%PDF-'))throw Error('فایل ذخیره‌شده PDF معتبر نیست؛ نسخه صحیح فایل را جایگزین کنید.');
  if(viewer.closed)return;
  const url=URL.createObjectURL(new Blob([blob],{type:'application/pdf'}));
  viewer.location.href=url;
  setTimeout(()=>URL.revokeObjectURL(url),120000);
 }catch(error){viewer.close();notice(error?.message||String(error),true)}
 finally{setBusy(button,false)}
}
let docxViewerPromise=null;
