  return{rows:grants.filter(grant=>grant?.effect!=='deny'&&grant?.resource_type==='site'&&grant?.resource_id&&grant?.user_id).map(grant=>({site_id:String(grant.resource_id),user_id:grant.user_id})),users:canonical,ready:true};
